    <div class="modal fade" x-ref="driverModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Pilih Driver</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control form-control-sm mb-3" placeholder="Cari kode atau nama driver..." x-model="driverSearch" @input.debounce.300ms="loadDrivers()"><div class="table-responsive"><table class="table table-sm table-hover"><thead><tr><th>Kode</th><th>Nama Driver</th><th></th></tr></thead><tbody><template x-for="row in drivers" :key="row.id"><tr><td x-text="row.code || '-' "></td><td x-text="row.name || 'Tanpa Nama'"></td><td><button type="button" class="btn btn-sm btn-primary" @click="chooseDriver(row)">Pilih</button></td></tr></template><tr x-show="!drivers.length"><td colspan="3" class="text-center text-muted">Tidak ada driver.</td></tr></tbody></table></div><div class="d-flex justify-content-between align-items-center"><button type="button" class="btn btn-sm btn-outline-secondary" @click="loadDrivers(driverPage - 1)" :disabled="driverPage <= 1">Sebelumnya</button><span class="small text-muted">Halaman <span x-text="driverPage"></span> / <span x-text="driverLastPage"></span></span><button type="button" class="btn btn-sm btn-outline-secondary" @click="loadDrivers(driverPage + 1)" :disabled="driverPage >= driverLastPage">Berikutnya</button></div></div></div></div></div>
    <div class="modal fade" x-ref="vehicleModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Pilih Kendaraan</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control form-control-sm mb-3" placeholder="Cari kode atau nama kendaraan..." x-model="vehicleSearch" @input.debounce.300ms="loadVehicles()"><div class="table-responsive"><table class="table table-sm table-hover"><thead><tr><th>Kode</th><th>Nama Kendaraan</th><th></th></tr></thead><tbody><template x-for="row in vehicles" :key="row.id"><tr><td x-text="row.code || '-' "></td><td x-text="row.name || '-' "></td><td><button type="button" class="btn btn-sm btn-primary" @click="chooseVehicle(row)">Pilih</button></td></tr></template><tr x-show="!vehicles.length"><td colspan="3" class="text-center text-muted">Tidak ada kendaraan.</td></tr></tbody></table></div><div class="d-flex justify-content-between align-items-center"><button type="button" class="btn btn-sm btn-outline-secondary" @click="loadVehicles(vehiclePage - 1)" :disabled="vehiclePage <= 1">Sebelumnya</button><span class="small text-muted">Halaman <span x-text="vehiclePage"></span> / <span x-text="vehicleLastPage"></span></span><button type="button" class="btn btn-sm btn-outline-secondary" @click="loadVehicles(vehiclePage + 1)" :disabled="vehiclePage >= vehicleLastPage">Berikutnya</button></div></div></div></div></div>
