<script>
document.addEventListener('alpine:init', () => {
    Alpine.data('suratJalanForm', (itemUrl, customerUrl, driverUrl, vehicleUrl, previewUrl, configuredTaxRate) => ({
        itemUrl, customerUrl, driverUrl, vehicleUrl, previewUrl, customer: @json(old('CUSTOMER_KODE', $expedisi?->CUSTOMER_KODE ?: $expedisi?->CUSTOMER)), customerName: @json(old('CUSTOMER_NAMA', $expedisi?->CUSTOMER)), vehicle: @json(old('KENDARAAN', $expedisi?->KENDARAAN)), vehicleName: @json(old('NAMA_KENDARAAN', $expedisi?->NAMA_KENDARAAN)), driver1: @json(old('DRIVER', $expedisi?->DRIVER)), driver1Name: @json(old('NAMA_DRIVER', $expedisi?->NAMA_DRIVER)), driver2: @json(old('DRIVER2', $expedisi?->DRIVER2)), driver2Name: @json(old('NAMA_DRIVER2', $expedisi?->NAMA_DRIVER2)), itemId: @json(old('item_expedisi_id', '')), itemName: @json(old('PESANAN', $expedisi?->PESANAN)), route: @json(old('rute', $expedisi?->rute)), itemType: @json(old('JENISHRG', $expedisi?->JENISHRG)), nosj: @json(old('NOSJ', $expedisi?->NOSJ)), itemSearch: '', itemPage: 1, itemLastPage: 1, items: [], customers: [], customerSearch: '', customerPage: 1, customerLastPage: 1, drivers: [], driverSearch: '', driverPage: 1, driverLastPage: 1, vehicles: [], vehicleSearch: '', vehiclePage: 1, vehicleLastPage: 1, driverTarget: 'DRIVER', saved: @json($editing), saving: false, printUrl: @json($editing ? route('expedisi.print.surjal', $expedisi) : ''), amount: Number(@json(old('JUMLAH', $expedisi?->JUMLAH ?: 0))), price: Number(@json(old('HARGA', $expedisi?->HARGA ?: 0))), discountRate: Number(@json(old('DISC', $expedisi?->DISC ?: 0))), taxRate: Number(configuredTaxRate || 0), deliveryCharge: Number(@json(old('DC', $expedisi?->DC ?: 0))), subtotal: 0, discount: 0, total: 0, grand: 0,
        async init() { this.calculate(); this.customerChanged(false); const form = this.$root.closest('form'); if (form && !form.dataset.suratJalanSubmitBound) { form.dataset.suratJalanSubmitBound = '1'; form.addEventListener('submit', event => { event.preventDefault(); this.submitForm(event); }); } if (!this.saved) await this.loadPreviewNoSj(); },
        money(value) { return new Intl.NumberFormat('id-ID').format(Number(value || 0)); },
        calculate() { this.subtotal = Math.round(this.amount * this.price); this.discount = Math.round(this.subtotal * this.discountRate / 100); this.total = this.subtotal - this.discount; this.grand = this.total + Math.round(this.total * this.taxRate / 100) + Number(this.deliveryCharge || 0); },
        customerChanged(load = true) { if (load) { this.items = []; this.itemName = ''; this.route = ''; this.price = 0; this.calculate(); } },
        vehicleChanged(event) { this.$root.querySelector('[name="NAMA_KENDARAAN"]').value = event.target.options[event.target.selectedIndex]?.dataset.name || ''; },
        async loadItems(page = 1) { if (!this.customer) return; const response = await fetch(`${this.itemUrl}?customer=${encodeURIComponent(this.customer)}&q=${encodeURIComponent(this.itemSearch)}&page=${page}`, {headers: {'Accept': 'application/json'}}); const payload = await response.json(); this.items = payload.data || []; this.itemPage = payload.current_page || 1; this.itemLastPage = payload.last_page || 1; },
        async loadCustomers(page = 1) { const response = await fetch(`${this.customerUrl}?q=${encodeURIComponent(this.customerSearch)}&page=${page}`, {headers: {'Accept': 'application/json'}}); const payload = await response.json(); this.customers = payload.data || []; this.customerPage = payload.current_page || 1; this.customerLastPage = payload.last_page || 1; },
        async loadDrivers(page = 1) { const response = await fetch(`${this.driverUrl}?q=${encodeURIComponent(this.driverSearch)}&page=${page}`, {headers: {'Accept': 'application/json'}}); const payload = await response.json(); this.drivers = payload.data || []; this.driverPage = payload.current_page || 1; this.driverLastPage = payload.last_page || 1; },
        async loadVehicles(page = 1) { const response = await fetch(`${this.vehicleUrl}?q=${encodeURIComponent(this.vehicleSearch)}&page=${page}`, {headers: {'Accept': 'application/json'}}); const payload = await response.json(); this.vehicles = payload.data || []; this.vehiclePage = payload.current_page || 1; this.vehicleLastPage = payload.last_page || 1; },
        async loadPreviewNoSj() { const response = await fetch(this.previewUrl, {headers: {'Accept': 'application/json'}}); if (response.ok) this.nosj = (await response.json()).nosj || ''; },
        async openCustomers() { await this.loadCustomers(); bootstrap.Modal.getOrCreateInstance(this.$refs.customerModal).show(); },
        async openDrivers(target) { this.driverTarget = target; await this.loadDrivers(); bootstrap.Modal.getOrCreateInstance(this.$refs.driverModal).show(); },
        async openVehicles() { await this.loadVehicles(); bootstrap.Modal.getOrCreateInstance(this.$refs.vehicleModal).show(); },
        async openItems() { await this.loadItems(); bootstrap.Modal.getOrCreateInstance(this.$refs.itemModal).show(); },
        chooseCustomer(row) { this.customer = row.CUSTOMER; this.customerName = row.NAMACUST || row.CUSTOMER; this.customerChanged(); bootstrap.Modal.getInstance(this.$refs.customerModal)?.hide(); },
        chooseDriver(row) { if (this.driverTarget === 'DRIVER2') { this.driver2 = row.code; this.driver2Name = row.name; } else { this.driver1 = row.code; this.driver1Name = row.name; } bootstrap.Modal.getInstance(this.$refs.driverModal)?.hide(); },
        chooseVehicle(row) { this.vehicle = row.code; this.vehicleName = row.name; bootstrap.Modal.getInstance(this.$refs.vehicleModal)?.hide(); },
        notify(message, icon = 'success') { if (window.Swal) return window.Swal.fire({icon, title: icon === 'success' ? 'Berhasil' : 'Periksa Data', text: message, timer: icon === 'success' ? 1800 : undefined, showConfirmButton: icon !== 'success'}); alert(message); },
        async submitForm(event) { if (this.saving) return; this.saving = true; const form = event.target; form.elements.KETERANGAN.value = `EXP ${this.itemName || ''} ${this.customerName || ''} KE ${form.elements.P_PENERIMA?.value || ''}`.trim(); try { const response = await fetch(form.action, {method: 'POST', body: new FormData(form), headers: {'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest'}}); const payload = await response.json(); if (!response.ok) { this.notify(payload.message || 'Data Surat Jalan belum valid.', 'error'); return; } this.saved = true; this.nosj = payload.data.NOSJ; this.printUrl = payload.print_url; this.notify(payload.message); } catch (error) { this.notify('Tidak dapat terhubung ke server. Silakan coba lagi.', 'error'); } finally { this.saving = false; } },
        newForm() { window.location.href = @js(route('expedisi.create')); },
        
        chooseItem(item) { this.itemId = item.KODE || ''; this.itemName = item.KETERANGAN || ''; this.route = item.RUTE || ''; this.itemType = item.JENIS || ''; this.amount = 1; this.price = Number(item.HARGA || 0); this.calculate(); bootstrap.Modal.getInstance(this.$refs.itemModal)?.hide(); }
    }));
});
</script>
@endpush
